  BatchPlanController_create: {
    parameters: {
      query?: never;
      header: {
        /** @description Stable key for replaying the same batch plan request */
        "Idempotency-Key": string;
      };
      path: {
        workId: string;
        branchId: string;
      };
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": {
          scope:
            | {
                /** @enum {string} */
                type: "chapter";
                chapterIds: string[];
              }
            | {
                /** @enum {string} */
                type: "volume";
                volumeNodeIds: string[];
              }
            | {
                /** @enum {string} */
                type: "range";
                fromChapterNumber: number;
                toChapterNumber: number;
              }
            | {
                /** @enum {string} */
                type: "book";
              };
          /**
           * @default per_volume
           * @enum {string}
           */
          approvalMode?: "per_chapter" | "per_volume" | "auto";
          /**
           * @default batch
           * @enum {string}
           */
          priorityClass?: "interactive" | "batch";
          /** @default 2 */
          maxConcurrency?: number;
          /**
           * @default [
           *       "prepare",
           *       "compile_context",
           *       "draft",
           *       "verify",
           *       "revise",
           *       "extract_facts",
           *       "await_review"
           *     ]
           */
          stepKeys?: (
            | "prepare"
            | "compile_context"
            | "draft"
            | "verify"
            | "revise"
            | "extract_facts"
            | "await_review"
          )[];
        };
      };
    };
    responses: {
      /** @description Persisted batch plan */
      202: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": {
            data: {
              id: string;
              jobId: string;
              workId: string;
              branchId: string;
              userId: string;
              /** @enum {string} */
              status:
                | "queued"
                | "preparing"
                | "running"
                | "paused"
                | "waiting_review"
                | "completed"
                | "failed"
                | "cancelled";
              scope:
                | {
                    /** @enum {string} */
                    type: "chapter";
                    chapterIds: string[];
                  }
                | {
                    /** @enum {string} */
                    type: "volume";
                    volumeNodeIds: string[];
                  }
                | {
                    /** @enum {string} */
                    type: "range";
                    fromChapterNumber: number;
                    toChapterNumber: number;
                  }
                | {
                    /** @enum {string} */
                    type: "book";
                  };
              /** @enum {string} */
              approvalMode: "per_chapter" | "per_volume" | "auto";
              /** @enum {string} */
              priorityClass: "interactive" | "batch";
              idempotencyKey: string;
              counts: {
                total: number;
                book: number;
                volume: number;
                chapter: number;
                step: number;
                pending: number;
                ready: number;
                running: number;
                paused: number;
                waiting_review: number;
                succeeded: number;
                failed: number;
                skipped: number;
                cancelled: number;
              };
              scheduling: {
                caps: {
                  global: number;
                  perWork: number;
                  perUser: number;
                };
                effectivePerWork: number;
                priority: number;
                initialRunnableKeys: string[];
              };
              /** Format: date-time */
              createdAt: string;
              /** Format: date-time */
              updatedAt: string;
            };
            /** Format: starts_with */
            requestId: string;
            /** @default {} */
            meta: {
              [key: string]: unknown;
            };
          };
        };
      };
    };
  };
